function send(res, status, body, type='text/plain') {
  res.writeHead(status, {'Content-Type': type, 'Cache-Control': 'no-store'});
  res.end(body);
}
function timingSafeEqual(a,b){
  const A=Buffer.from(a||''); const B=Buffer.from(b||'');
  if(A.length!==B.length) return false;
  return crypto.timingSafeEqual(A,B);
}
function authorized(req){
  if(!PASSWORD) return true;
  const cookie=req.headers.cookie||'';
  return cookie.split(';').some(x=>x.trim().startsWith('dash_auth=') && timingSafeEqual(decodeURIComponent(x.trim().slice(10)), PASSWORD));
}

const SMS_QUEUE_PATH = path.join(ROOT,'data','day0-sms-queue.json');
const SMS_LOG_PATH = process.env.SMS_DAY0_LOG_PATH || '/tmp/moniepoint_day0_sms_sent_log.json';
function readJsonFileSafe(file, fallback){try{return JSON.parse(fs.readFileSync(file,'utf8'));}catch(e){return fallback;}}
function writeJsonFileSafe(file, data){try{fs.writeFileSync(file, JSON.stringify(data,null,2)); return true;}catch(e){return false;}}
function normalizeSmsPhone(phone){let p=String(phone||'').replace(/\D/g,''); if(p.startsWith('0')&&p.length===11)p='234'+p.slice(1); return p;}
function smsQueuePathFor(day){return path.join(ROOT,'data',day==='approved'?'approved-sms-queue.json':`${day}-sms-queue.json`);}
function smsLogPathFor(day){return process.env[`SMS_${day.toUpperCase().replace('-','_')}_LOG_PATH`] || `/tmp/moniepoint_${day.replace('-','_')}_sms_sent_log.json`;}
function smsLive247Send(item){return new Promise((resolve)=>{const apiKey=process.env.SMSLIVE247_API_KEY; const senderID=process.env.SMSLIVE247_SENDER_ID; if(!apiKey||!senderID)return resolve({ok:false,statusCode:null,response:'Missing SMSLIVE247_API_KEY or SMSLIVE247_SENDER_ID'}); const body=JSON.stringify({senderID, mobileNumber:normalizeSmsPhone(item.phone), messageText:item.message}); const req=https.request('https://api.smslive247.com/api/v4/sms',{method:'POST',headers:{'Authorization':apiKey,'accept':'application/json','content-type':'application/*+json','content-length':Buffer.byteLength(body)}},res=>{let data='';res.on('data',c=>data+=c);res.on('end',()=>resolve({ok:res.statusCode>=200&&res.statusCode<300,statusCode:res.statusCode,response:data.slice(0,1000)}));}); req.on('error',e=>resolve({ok:false,statusCode:null,response:String(e.message||e)})); req.setTimeout(30000,()=>{req.destroy(new Error('SMSLive247 timeout'));}); req.write(body); req.end();});}
function smsStatusPayloadFor(day){const queue=readJsonFileSafe(smsQueuePathFor(day),{items:[]}); const log=readJsonFileSafe(smsLogPathFor(day),{sent:[]}); const sentKeys=new Set((log.sent||[]).filter(x=>x.ok).map(x=>x.key)); const items=queue.items||[]; const pending=items.filter(x=>!sentKeys.has(`${normalizeSmsPhone(x.phone)}|${x.message}`)); const byWorkflow=items.reduce((a,x)=>{const k=x.workflow||'unknown';a[k]=(a[k]||0)+1;return a;},{}); return {queue,log,items,pending,sentKeys,payload:{ready:!!(process.env.SMSLIVE247_API_KEY&&process.env.SMSLIVE247_SENDER_ID),env_ready:!!(process.env.SMSLIVE247_API_KEY&&process.env.SMSLIVE247_SENDER_ID),total:items.length,sent_count:items.length-pending.length,pending_count:pending.length,queue_name:queue.queue_name||day,day,by_workflow:byWorkflow}};}
function smsStatusPayload(){return smsStatusPayloadFor('day0');}

function loginPage(msg){return `<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard Login</title><style>body{margin:0;background:linear-gradient(135deg,#06101f,#0f1c2e 55%,#152942);color:#eaf2ff;font-family:Arial;display:grid;place-items:center;min-height:100vh}.box{background:#0f1c2e;border:1px solid #24364f;padding:28px;border-radius:22px;width:min(420px,92vw);box-shadow:0 24px 80px rgba(0,0,0,.35);text-align:center}.loginPhoto{width:156px;height:156px;object-fit:cover;border-radius:50%;border:4px solid #1d6bff;box-shadow:0 12px 35px rgba(0,0,0,.35);display:block;margin:0 auto 18px}h2{margin:6px 0 6px}p{color:#b8c5d8}input,button{width:100%;padding:12px;margin-top:12px;border-radius:10px;border:1px solid #28415f;background:#081423;color:#fff}button{background:#1d6bff;font-weight:bold;cursor:pointer}</style></head><body><form class="box" method="post" action="/login"><img class="loginPhoto" src="/assets/collins-login-photo.jpg" alt="Collins Ajunufe"><h2>Moniepoint Dashboard</h2><p>Enter dashboard password.</p><p style="font-size:12px;color:#9fb2cc">App version: ${APP_VERSION}</p>${msg?`<p style="color:#ff5d5d">${msg}</p>`:''}<input type="password" name="password" autofocus><button>Open dashboard</button></form></body></html>`}

const server = http.createServer((req,res)=>{
  const url = new URL(req.url, `http://${req.headers.host}`);
  if(url.pathname==='/health') return send(res,200,JSON.stringify({ok:true,version:APP_VERSION,hasEmbeddedIndex:true,hasEmbeddedData:true}),'application/json');
  if(url.pathname==='/assets/collins-login-photo.jpg') {
    return fs.readFile(path.join(ROOT,'assets','collins-login-photo.jpg'),(e,d)=> send(res,e?404:200,e?'Not found':d,'image/jpeg'));
  }
  if(url.pathname==='/login' && req.method==='GET') {
    if(PASSWORD && !authorized(req)) return send(res,200,loginPage(''),'text/html');
    res.writeHead(302, {'Location':'/'}); res.end(); return;
  }
  if(url.pathname==='/login' && req.method==='POST'){
    let body=''; req.on('data',c=>body+=c); req.on('end',()=>{
      const pass=new URLSearchParams(body).get('password')||'';
      if(timingSafeEqual(pass,PASSWORD)) {res.writeHead(302, {'Set-Cookie': `dash_auth=${encodeURIComponent(pass)}; HttpOnly; SameSite=Lax; Path=/`, 'Location':'/'}); res.end();}
      else send(res,401,loginPage('Wrong password'),'text/html');
    }); return;
  }
  if(url.pathname==='/logout') {
    res.writeHead(302, {
      'Set-Cookie': 'dash_auth=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT',
      'Location': '/login'
    });
    res.end(); return;
  }
  if(PASSWORD && !authorized(req)) return send(res,200,loginPage(''),'text/html');
  if(url.pathname==='/api/workflows/day0-sms/status' || url.pathname==='/api/workflows/day2-sms/status' || url.pathname==='/api/workflows/approved-sms/status') {
    const day=url.pathname.includes('approved')?'approved':(url.pathname.includes('day2')?'day2':'day0');
    const s=smsStatusPayloadFor(day);
    return send(res,200,JSON.stringify(s.payload),'application/json');
  }
  if((url.pathname==='/api/workflows/day0-sms/send' || url.pathname==='/api/workflows/day2-sms/send' || url.pathname==='/api/workflows/approved-sms/send') && req.method==='POST') {
    (async()=>{
      const day=url.pathname.includes('approved')?'approved':(url.pathname.includes('day2')?'day2':'day0');
      const s=smsStatusPayloadFor(day);
      if(!s.payload.env_ready) return send(res,500,JSON.stringify({...s.payload,error:'Missing SMSLIVE247_API_KEY or SMSLIVE247_SENDER_ID in Render env'}),'application/json');
      const log=s.log && Array.isArray(s.log.sent)?s.log:{sent:[]};
      const results=[];
      for(const item of s.pending){
        const key=`${normalizeSmsPhone(item.phone)}|${item.message}`;
        const result=await smsLive247Send(item);
        const rec={timestamp:new Date().toISOString(),key,workflow:item.workflow,business:item.business,phone:normalizeSmsPhone(item.phone),ok:result.ok,statusCode:result.statusCode,response:result.response};
        log.sent.push(rec); results.push(rec);
      }
      writeJsonFileSafe(smsLogPathFor(s.payload.day||'day0'),log);
      return send(res,200,JSON.stringify({ok:true,attempted:results.length,sent:results.filter(x=>x.ok).length,failed:results.filter(x=>!x.ok).length,results}),'application/json');
    })(); return;
  }
  if(url.pathname==='/api/data') {
    const dataPath = path.join(ROOT,'data','dashboard-data.json');
    return fs.readFile(dataPath,'utf8',(e,d)=> send(res,200,e ? EMBEDDED_DATA : d,'application/json'));
  }
  if(url.pathname==='/' || url.pathname==='/index.html') return send(res,200,EMBEDDED_INDEX,'text/html');
  let file = url.pathname;
  file = path.normalize(file).replace(/^\.\.(?:[\/]|$)/, '');
  let full = path.join(ROOT,file);
  if(!full.startsWith(ROOT)) return send(res,403,'Forbidden');
  fs.readFile(full,(e,d)=>{
    if(e) return send(res,404,'Not found');
    const ext=path.extname(full).toLowerCase();
    const type={'.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg'}[ext]||'application/octet-stream';
    send(res,200,d,type);
  });
});
server.listen(PORT,()=>console.log(`Moniepoint dashboard running on http://localhost:${PORT} version ${APP_VERSION}`));
